# playful.py: ABCmouse-inspired (original) redesign of the welcome, sign-in and sign-up pages.
# Run from the repo root. Refuses to overwrite if WelcomeScreen/LoginScreen changed since staging.
import base64, hashlib, os, sys
EXPECT = {'app/src/screens/WelcomeScreen.tsx': '542cf807cabdeea8c5e744c8478ef26d', 'app/src/screens/LoginScreen.tsx': '477b4f9ef002fc0c6f04c4437c52a6f0'}
for p, m in EXPECT.items():
    got = hashlib.md5(open(p, 'rb').read()).hexdigest()
    if got != m:
        sys.exit(f'{p} changed since staging ({got}); not applying')
if os.path.exists('app/src/components/Playful.tsx'):
    sys.exit('app/src/components/Playful.tsx already exists; not applying')
PAYLOAD = {'app/src/components/Playful.tsx': '', 'app/src/screens/WelcomeScreen.tsx': '', 'app/src/screens/LoginScreen.tsx': ''}
WANT = {'app/src/components/Playful.tsx': '8acf6804e2687aa467b540242bfda3c6', 'app/src/screens/WelcomeScreen.tsx': '77d01dd7268f4113497e23c34dea4226', 'app/src/screens/LoginScreen.tsx': '6ee4cf0fc4dda556e0b59a15080fd2bc'}
for p, b in PAYLOAD.items():
    open(p, 'wb').write(base64.b64decode(b))
    assert hashlib.md5(open(p, 'rb').read()).hexdigest() == WANT[p], p
    print('wrote', p, WANT[p])
